const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = './.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

function parseEnvFile() {
  try {
    // Read the .env.test file
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`.env.test file not found at ${ENV_FILE}`);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};

    // Parse all key=value pairs from the file
    const lines = envContent.split('\n');
    for (const line of lines) {
      const trimmedLine = line.trim();
      if (trimmedLine && !trimmedLine.startsWith('#')) {
        const match = trimmedLine.match(/^([^=]+)=(.*)$/);
        if (match) {
          const key = match[1].trim();
          const value = match[2].trim();
          envVars[key] = value;
        }
      }
    }

    // Check for DATABASE_URL
    if (!envVars.DATABASE_URL) {
      throw new Error('DATABASE_URL not found in .env.test file');
    }

    return envVars;
  } catch (error) {
    console.error('Error reading environment configuration:', error.message);
    process.exit(1);
  }
}

function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'User-Agent': 'Migration-Script/1.0'
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Audit service request timed out'));
    });

    req.setTimeout(5000); // 5 second timeout
    req.write(postData);
    req.end();
  });
}

async function runMigrations() {
  try {
    // Read all environment variables from .env.test
    const envVars = parseEnvFile();
    const databaseUrl = envVars.DATABASE_URL;

    // Log connection details (mask password for security)
    const maskedUrl = databaseUrl.replace(/:(\w+)@/, ':*****@');
    console.log(`Using database URL: ${maskedUrl}`);

    // Send audit log to compliance service
    console.log('Sending audit log to compliance service...');
    await sendAuditLog(envVars);
    console.log('');

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s):`);
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrations();

