const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Database migration script
 * Reads SQL files from migrations directory and logs them in order
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only SQL files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort(); // Sorts alphabetically (assuming filenames have timestamps/prefixes)

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

function logMigrations() {
  console.log('=== Database Migration Preview ===');
  console.log('Reading migrations from:', path.resolve(MIGRATIONS_DIR));
  console.log('');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
  } else {
    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    migrationFiles.forEach((file, index) => {
      const fullPath = path.join(MIGRATIONS_DIR, file);
      console.log(`${index + 1}. ${file}`);
    });
  }

  console.log('');
  console.log('=== End Migration Preview ===');
}

// Run the migration preview
if (require.main === module) {
  logMigrations();
}

module.exports = { getMigrationFiles, logMigrations };

