const fs = require('fs/promises');
const path = require('path');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = './.env.test';

/**
 * Reads and parses a .env file to extract environment variables
 * @param {string} filePath - Path to the .env file
 * @returns {Promise<Object>} A promise that resolves to an object of environment variables
 */
async function readEnvFile(filePath) {
  try {
    const envContent = await fs.readFile(filePath, 'utf-8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (line.trim() && !line.trim().startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          const value = valueParts.join('=').trim();
          // Remove quotes if present
          envVars[key.trim()] = value.replace(/^["']|["']$/g, '');
        }
      }
    });

    return envVars;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Environment file '${filePath}' not found.`);
    } else {
      console.error('Error reading environment file:', error);
    }
    return {};
  }
}

/**
 * Gets a list of SQL migration files from the migrations directory,
 * sorted in the order they would be applied.
 * @returns {Promise<string[]>} A promise that resolves to an array of filenames.
 */
async function getMigrationFiles() {
  try {
    const files = await fs.readdir(MIGRATIONS_DIR);
    // Filter for .sql files and sort them lexicographically.
    // This assumes files are named with a sortable prefix like a timestamp
    // (e.g., 20240101120000_migration_name.sql) or a sequence number
    // (e.g., 001_migration_name.sql).
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found.`);
    } else {
      console.error('Error reading migrations directory:', error);
    }
    return []; // Return an empty array on error
  }
}

/**
 * Simulates database connection (logs success message without actually connecting)
 * @param {string} connectionString - The database connection string
 */
async function simulateDatabaseConnection(connectionString) {
  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in environment variables.');
    return false;
  }

  // Mask sensitive information in connection string for logging
  const maskedConnectionString = connectionString.replace(/:(\w+)@/, ':***@');

  console.log(`Connecting to database: ${maskedConnectionString}`);

  // Simulate connection delay
  await new Promise(resolve => setTimeout(resolve, 100));

  console.log('✓ Database connection successful (simulated)');
  console.log('');
  return true;
}

/**
 * Logs the filenames of SQL migrations that would be applied,
 * in the order they would be run.
