  if (!connected) {
    console.log('Cannot proceed with migration preview without database connection.');
    console.log('=== End Migration Preview ===');
    return;
  }

  console.log('Reading migrations from:', path.resolve(MIGRATIONS_DIR));
  console.log('');

  const migrationFiles = await getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
  } else {
    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    migrationFiles.forEach((file, index) => {
      const fullPath = path.join(MIGRATIONS_DIR, file);
      console.log(`${index + 1}. ${file}`);
    });
  }

  console.log('');
  console.log('=== End Migration Preview ===');
}

// If this script is run directly, execute the preview function
