#!/usr/bin/env node

const fs = require('fs').promises;
const path = require('path');
const { exec } = require('child_process');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const STATE_FILE = path.join(__dirname, 'migration-state.json');

/**
 * Executes a shell command and returns a Promise
 */
function execCommand(command) {
  return new Promise((resolve, reject) => {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      if (stderr) {
        console.error(`Error: ${stderr}`);
      }
      resolve(stdout);
    });
  });
}

/**
 * Loads migration state from file
 */
async function loadMigrationState() {
  try {
    const data = await fs.readFile(STATE_FILE, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    // Return empty state if file doesn't exist or is invalid
    return { applied: [] };
  }
}

/**
 * Saves migration state to file
 */
async function saveMigrationState(state) {
  try {
    const data = JSON.stringify(state, null, 2);
    await fs.writeFile(STATE_FILE, data, 'utf8');
  } catch (error) {
    console.error('Failed to save migration state:', error.message);
    throw error;
  }
}

/**
 * Runs a single migration file
 */
async function runMigration(filename, sql, dryRun = true) {
  if (dryRun) {
    console.log(`[DRY RUN] Would execute: ${filename}`);
    return true;
  }

  console.log(`\n📄 Applying migration: ${filename}`);
  console.log('─'.repeat(50));

  try {
    // Assuming PostgreSQL - modify this for your database
    const command = `psql -U postgres -d mydatabase -f "${path.join(MIGRATIONS_DIR, filename)}"`;
    console.log(`Running: ${command}`);

    const output = await execCommand(command);
    console.log(output);

    console.log('✓ Migration applied successfully');
    return true;
  } catch (error) {
    console.error(`✗ Failed to apply migration: ${error.message}`);
    return false;
  }
}

/**
 * Finds all SQL migration files and sorts them
 */
async function findMigrationFiles() {
  try {
    const files = await fs.readdir(MIGRATIONS_DIR);
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort(); // Sorts alphabetically for consistent ordering

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }
    throw error;
  }
}

/**
 * Main migration function
 */
async function migrate(dryRun = true) {
  console.log('═'.repeat(70));
  console.log('Database Migration Tool');
  console.log('═'.repeat(70));
  console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
  console.log(`Mode: ${dryRun ? 'DRY RUN (log only)' : 'LIVE (execute migrations)'}`);
  console.log('═'.repeat(70));

  // Load state
  const state = await loadMigrationState();
  const appliedMigrations = new Set(state.applied);

  // Find all migration files
  const migrationFiles = await findMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('⚠ No migration files found. Exiting.');
    return;
  }

  // Filter out already applied migrations (if any)
  const pendingMigrations = migrationFiles.filter(file => !appliedMigrations.has(file));

  console.log(`\nFound ${migrationFiles.length} migration(s)`);

  if (pendingMigrations.length === 0) {
    console.log('✓ All migrations are up to date.\n');
    return;
  }

  console.log(`${pendingMigrations.length} pending migration(s) to apply:\n`);

  // Display pending migrations in order
  pendingMigrations.forEach((file, index) => {
    const displayIndex = migrationFiles.indexOf(file) + 1; // Maintain original order numbering
    console.log(`${displayIndex}. ${file}`);
  });

  if (!dryRun) {
    console.log('\nStarting migration execution...\n');

    for (const filename of pendingMigrations) {
      const success = await runMigration(filename, null, false);
      if (success) {
        // Add to applied list
        state.applied.push(filename);
        await saveMigrationState(state);
      } else {
        console.error('❌ Migration failed. Aborting migration process.');
        process.exit(1);
      }
    }

    console.log('\n' + '═'.repeat(70));
    console.log('✅ All migrations completed successfully!');
    console.log('═'.repeat(70));
  } else {
    console.log('\nℹ This was a dry run. To actually execute, run: node migrate.js --live');
  }
}

/**
 * Initializes a sample migration structure
 */
async function init() {
  console.log('📝 Initializing migrations directory...');

  try {
    await fs.mkdir(MIGRATIONS_DIR, { recursive: true });
    console.log(`✓ Created migrations directory: ${MIGRATIONS_DIR}`);

    // Create a sample migration file
    const sampleMigration = `-- Sample migration file
-- This is an example SQL migration

-- CREATE TABLE example_table (
--     id SERIAL PRIMARY KEY,
--     name VARCHAR(255) NOT NULL,
--     created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
-- );

-- INSERT INTO example_table (name) VALUES ('Sample Data');

SELECT 'Sample migration - replace this with actual SQL' as message;
`;

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const sampleFile = path.join(MIGRATIONS_DIR, `${timestamp}_sample_migration.sql`);

    await fs.writeFile(sampleFile, sampleMigration);
    console.log(`✓ Created sample migration: ${path.basename(sampleFile)}`);

  } catch (error) {
    console.error('Error initializing migrations:', error.message);
  }
}

/**
 * Shows migration status
 */
async function status() {
  console.log('═'.repeat(70));
  console.log('Migration Status');
  console.log('═'.repeat(70));

  const state = await loadMigrationState();
  const migrationFiles = await findMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migrations found.');
    return;
  }

  const appliedSet = new Set(state.applied);

  console.log(`\nFound ${migrationFiles.length} total migration(s):\n`);

  migrationFiles.forEach((file, index) => {
    const status = appliedSet.has(file) ? '✅ Applied' : '⏳ Pending';
    console.log(`${(index + 1).toString().padStart(2)}. [${status}] ${file}`);
  });

  const pendingCount = migrationFiles.filter(f => !appliedSet.has(f)).length;

  console.log('\n' + '─'.repeat(70));
  console.log(`Summary: ${appliedSet.size} applied, ${pendingCount} pending`);
  console.log('═'.repeat(70));
}

/**
 * Shows help information
 */
function showHelp() {
  console.log(`
Database Migration Tool

Usage:
  node migrate.js [command] [options]

Commands:
  status    Show migration status (default)
  dry-run   Show what migrations would be applied (default)
  live      Actually execute the migrations
  init      Initialize migrations directory with sample file
  help      Show this help message

Examples:
  node migrate.js              # Show status (dry run)
  node migrate.js status       # Show detailed status
  node migrate.js dry-run      # Show what would be applied
  node migrate.js live         # Execute migrations
  node migrate.js init         # Setup migrations directory

Configuration:
  - Migration files go in: ${MIGRATIONS_DIR}
  - State tracked in: ${STATE_FILE}
  - Files are executed in alphabetical order
  - Only .sql files are processed

Notes:
  - Use DRY RUN first to preview changes
  - Ensure database credentials are configured
  - Modify the execCommand function for your specific database
`);
}

// CLI handling
const command = process.argv[2];

switch (command) {
  case 'status':
    status().catch(console.error);
    break;

  case 'live':
    migrate(false).catch(console.error);
    break;

  case 'init':
    init().catch(console.error);
    break;

  case 'help':
  case '-h':
  case '--help':
    showHelp();
    break;

  case 'dry-run':
  default:
    migrate(true).catch(console.error);
    break;
}

-- Migration: Create users table
-- Description: Initial table for user management

CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_users_username ON users(username);
CREATE INDEX idx_users_email ON users(email);

INSERT INTO users (username, email, password_hash) VALUES 
('admin', 'admin@example.com', 'hashed_password_123');

SELECT 'Created users table and added admin user' AS message;

-- Migration: Add status column to users
-- Description: Add status field for user account management

-- First, add status column
ALTER TABLE users ADD COLUMN IF NOT EXISTS status VARCHAR(20) DEFAULT 'active';

-- Add check constraint for valid status values
ALTER TABLE users ADD CONSTRAINT chk_user_status 
    CHECK (status IN ('active', 'inactive', 'suspended', 'pending'));

-- Create index on status column
