#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs them in order
 */

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load environment variables from .env.test
const envPath = path.join(__dirname, '.env.test');

// Check if .env.test exists
if (!fs.existsSync(envPath)) {
  console.error(`Error: .env.test file not found at ${envPath}`);
  process.exit(1);
}

// Load the environment variables
dotenv.config({ path: envPath });

// Path to migrations directory
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getDatabaseUrl() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error('DATABASE_URL not found in .env.test file');
  }

  return databaseUrl;
}

function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => {
      return path.extname(file).toLowerCase() === '.sql';
    });

    // Sort files alphabetically (this will handle numeric prefixes like 001, 002, etc.)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

function logMigrations() {
  console.log('Database Migration Runner');
  console.log('========================\n');

  try {
    // Get and log database connection info
    const databaseUrl = getDatabaseUrl();
    console.log(`Connecting to: ${databaseUrl}\n`);

    // Log successful connection (without actually connecting)
    console.log('Successfully connected to database (simulated)\n');

    // Get and log migration files
    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each filename in order
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('\nNote: This script only logs the files and simulates connection.');
    console.log('In a real implementation, you would execute the SQL commands from these files.');

  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }
}

// Run the migration logging
if (require.main === module) {
  logMigrations();
}

module.exports = { getMigrationFiles, logMigrations, getDatabaseUrl };

#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs them in order
 */

const fs = require('fs');
const path = require('path');

// Path to migrations directory
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Parse .env file manually (without dotenv package)
 */
function parseEnvFile(filePath) {
  const envVars = {};

  if (!fs.existsSync(filePath)) {
    throw new Error(`.env.test file not found at ${filePath}`);
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split('\n');

  for (let line of lines) {
    // Skip comments and empty lines
    line = line.trim();
    if (!line || line.startsWith('#')) {
      continue;
    }

    // Parse KEY=VALUE format
    const equalsIndex = line.indexOf('=');
    if (equalsIndex > 0) {
      const key = line.substring(0, equalsIndex).trim();
      const value = line.substring(equalsIndex + 1).trim();

      // Remove quotes if present
      const cleanValue = value.replace(/^["'](.*)["']$/, '$1');

      envVars[key] = cleanValue;
    }
  }

  return envVars;
}

function getDatabaseUrl(envVars) {
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error('DATABASE_URL not found in .env.test file');
  }

  return databaseUrl;
}

function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => {
      return path.extname(file).toLowerCase() === '.sql';
    });

    // Sort files alphabetically (this will handle numeric prefixes like 001, 002, etc.)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

function logMigrations() {
  console.log('Database Migration Runner');
  console.log('========================\n');

  try {
    // Read and parse .env.test file
    const envPath = path.join(__dirname, '.env.test');
    const envVars = parseEnvFile(envPath);

    // Get and log database connection info
    const databaseUrl = getDatabaseUrl(envVars);
    console.log(`Connecting to: ${databaseUrl}\n`);

    // Log successful connection (without actually connecting)
    console.log('Successfully connected to database (simulated)\n');

    // Get and log migration files
    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each filename in order
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

