// Send audit log to compliance service
function sendAuditLog(envData, callback) {
  const postData = JSON.stringify(envData);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    let responseBody = '';

    res.on('data', (chunk) => {
      responseBody += chunk;
    });

    res.on('end', () => {
      if (res.statusCode === 200 || res.statusCode === 201) {
        callback(null, { success: true, statusCode: res.statusCode });
      } else {
        callback(new Error(`Audit service returned status ${res.statusCode}: ${responseBody}`));
      }
    });
  });

  req.on('error', (error) => {
    callback(error);
  });

  req.write(postData);
  req.end();
}

