#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename in the order they would be applied.
 */

const fs = require('fs').promises;
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

async function listMigrations() {
  try {
    // Check if migrations directory exists
    await fs.access(MIGRATIONS_DIR);

    // Read all files from migrations directory
    const files = await fs.readdir(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    // This ensures proper order for timestamped or numbered migrations
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

    if (sqlFiles.length === 0) {
      console.log(`No SQL migration files found in '${MIGRATIONS_DIR}'`);
      console.log('Create migration files with .sql extension to get started.');
      return;
    }

    console.log('='.repeat(60));
    console.log('Database Migration Plan');
    console.log('='.repeat(60));
    console.log(`\nFound ${sqlFiles.length} migration(s) to apply:\n`);

    sqlFiles.forEach((file, index) => {
      const fullPath = path.join(MIGRATIONS_DIR, file);
      console.log(`${String(index + 1).padStart(3, '0')}. ${file}`);
    });

    console.log('\n' + '='.repeat(60));
    console.log('End of migration list');
    console.log('='.repeat(60));

  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      console.error('Please create the directory and add your SQL migration files.');
    } else {
      console.error('Error reading migrations directory:', error.message);
    }
    process.exit(1);
  }
}

// Run the migration list
listMigrations().catch(console.error);

