const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';

function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
      console.log('Please create the directory and add your SQL migration files.');
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort(); // Sort files alphabetically (standard migration naming convention)

    if (sqlFiles.length === 0) {
      console.log(`No SQL files found in "${MIGRATIONS_DIR}" directory.`);
      return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s) in "${MIGRATIONS_DIR}":\n`);

    // Log each filename in order
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrations();

-- Create posts table
