const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

// Logging utilities with colors
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m'
};

function logInfo(message) {
  console.log(`${colors.blue}ℹ${colors.reset} ${message}`);
}

function logSuccess(message) {
  console.log(`${colors.green}✓${colors.reset} ${message}`);
}

function logWarning(message) {
  console.log(`${colors.yellow}⚠${colors.reset} ${message}`);
}

function logError(message) {
  console.error(`${colors.red}✗${colors.reset} ${message}`);
}

function logStep(step, message) {
  console.log(`\n${colors.magenta}[Step ${step}]${colors.reset} ${message}`);
}

// Read and parse .env.test file
function loadEnvFile(filePath) {
  logInfo(`Attempting to load environment file: ${filePath}`);

  if (!fs.existsSync(filePath)) {
    logWarning(`Environment file not found at: ${filePath}`);
    return null;
  }

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};
    let validLines = 0;

    content.split('\n').forEach((line, index) => {
      const trimmedLine = line.trim();
      if (trimmedLine && !trimmedLine.startsWith('#')) {
        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex > 0) {
          const key = trimmedLine.substring(0, equalsIndex).trim();
          const value = trimmedLine.substring(equalsIndex + 1).trim();
          if (key && value) {
            envVars[key] = value;
            validLines++;
          } else {
            logWarning(`Skipping invalid line ${index + 1}: ${trimmedLine}`);
          }
        } else {
          logWarning(`Skipping malformed line ${index + 1}: ${trimmedLine}`);
        }
      }
    });

    logSuccess(`Successfully loaded ${validLines} environment variable(s)`);
    return envVars;
  } catch (error) {
    logError(`Failed to read environment file: ${error.message}`);
    throw error;
  }
}

