async function runMigrations() {
  const startTime = Date.now();
  let step = 1;

  try {
    // Load environment variables from .env.test
    logStep(step++, 'Loading environment configuration');
    const envFilePath = path.join(__dirname, '.env.test');
    const envVars = loadEnvFile(envFilePath);

    if (!envVars) {
      throw new Error(`.env.test file not found at: ${envFilePath}`);
    }

    // Get DATABASE_URL from environment
    logStep(step++, 'Validating database connection string');
    const databaseUrl = envVars.DATABASE_URL;
    if (!databaseUrl) {
      throw new Error('DATABASE_URL not found in .env.test file');
    }

    // Validate database URL format
    const urlPattern = /^(postgres|postgresql|mysql|mongodb):\/\//i;
    if (!urlPattern.test(databaseUrl)) {
      logWarning(`Database URL does not match common patterns. Expected format: postgres://... or mysql://...`);
    }

    // Log successful connection (without actually connecting)
    logSuccess('Connected successfully to database (simulated)');
    const maskedUrl = databaseUrl.replace(/:(?!.*:)[^@]+@/, ':***@');
    logInfo(`Database URL: ${maskedUrl}`);

    // Check migrations directory
    logStep(step++, 'Scanning migrations directory');
    const migrationsDir = path.join(__dirname, 'migrations');
    logInfo(`Migrations directory path: ${migrationsDir}`);

    if (!fs.existsSync(migrationsDir)) {
      throw new Error(`Migrations directory does not exist: ${migrationsDir}`);
    }

    logSuccess('Migrations directory found');

    // Read all files in migrations directory
    logStep(step++, 'Reading migration files');
    let files;
    try {
      files = fs.readdirSync(migrationsDir);
      logInfo(`Found ${files.length} total file(s) in directory`);
    } catch (error) {
      throw new Error(`Failed to read migrations directory: ${error.message}`);
    }

    // Filter for SQL files only
    logStep(step++, 'Filtering SQL migration files');
    const sqlFiles = files.filter(file => {
      const ext = path.extname(file).toLowerCase();
      const isSql = ext === '.sql';
      if (!isSql) {
        logInfo(`Skipping non-SQL file: ${file}`);
      }
      return isSql;
    });

    // Sort files alphabetically to ensure consistent order
    sqlFiles.sort();

    if (sqlFiles.length === 0) {
      logWarning('No SQL migration files found');
      logInfo('To add migrations, place .sql files in the migrations directory');
      return;
    }

    logSuccess(`Found ${sqlFiles.length} migration file(s)`);

    // Display migration files
    logStep(step++, 'Displaying migration execution order');
    console.log(`\n${colors.bright}Migration Execution Plan:${colors.reset}\n`);

    sqlFiles.forEach((file, index) => {
      const fullPath = path.join(migrationsDir, file);
      let fileInfo = '';

      try {
        const stats = fs.statSync(fullPath);
        const sizeKB = (stats.size / 1024).toFixed(2);
        fileInfo = ` (${sizeKB} KB)`;
      } catch (error) {
        fileInfo = ' (size unknown)';
      }

      const prefix = sqlFiles.length > 9 && index < 9 ? ' ' : '';
      console.log(`  ${prefix}${index + 1}. ${colors.cyan}${file}${colors.reset}${fileInfo}`);
    });

    // Summary
    const endTime = Date.now();
    const duration = ((endTime - startTime) / 1000).toFixed(2);

    console.log(`\n${colors.bright}Migration Summary:${colors.reset}`);
    console.log(`  • Total migrations: ${sqlFiles.length}`);
    console.log(`  • Time elapsed: ${duration}s`);
    console.log(`  • Status: ${colors.green}Ready to execute${colors.reset}`);
    console.log(`\n${colors.yellow}Note: This is a preview. No actual database changes were made.${colors.reset}`);

  } catch (error) {
    logError(`Migration failed at step ${step}: ${error.message}`);

    if (error.stack) {
      logInfo('Stack trace:');
      console.error(colors.red + error.stack + colors.reset);
    }

    logWarning('To resolve this issue:');
    console.log('  1. Ensure .env.test exists with DATABASE_URL');
    console.log('  2. Create a migrations directory with SQL files');
    console.log('  3. Check file permissions and paths');

    process.exit(1);
  }
}

