const http = require('http');

async function parseEnvFile() {
  const envFilePath = path.join(__dirname, '.env.test');

  try {
    // Read the .env.test file
    const envContent = await fs.readFile(envFilePath, 'utf8');

    // Parse all key-value pairs
    const envVars = {};
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE format
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();
        envVars[key] = value;
      }
    }

    if (Object.keys(envVars).length === 0) {
      throw new Error('No valid environment variables found in .env.test file');
    }

    // Check for DATABASE_URL specifically
    if (!envVars.DATABASE_URL) {
      throw new Error('DATABASE_URL not found in .env.test file');
    }

    return envVars;
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error('.env.test file not found');
    }
    throw error;
  }
}

