      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({
            statusCode: res.statusCode,
            statusMessage: res.statusMessage,
            data: responseData
          });
        } else {
          reject(new Error(`Audit service returned ${res.statusCode}: ${res.statusMessage}`));
        }
