const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

function loadEnvVariable(filePath, variableName) {
  try {
    const envContent = fs.readFileSync(filePath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip comments and empty lines
      if (trimmedLine.startsWith('#') || trimmedLine === '') {
        continue;
      }

      // Parse KEY=VALUE format
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex > 0) {
        const key = trimmedLine.substring(0, equalsIndex).trim();
        const value = trimmedLine.substring(equalsIndex + 1).trim();

        if (key === variableName) {
          // Remove quotes if present
          return value.replace(/^["'](.*)["']$/, '$1');
        }
      }
    }
  } catch (error) {
    console.error(`Error reading ${filePath}: ${error.message}`);
    process.exit(1);
  }

  console.error(`Error: ${variableName} not found in ${filePath}`);
  process.exit(1);
}

function maskDatabaseUrl(url) {
  try {
    const urlObj = new URL(url);
    if (urlObj.password) {
      urlObj.password = '***';
    }
    return urlObj.toString();
  } catch {
    // If URL parsing fails, return original with masked password pattern
    return url.replace(/:[^:@]+@/, ':***@');
  }
}

function previewMigrations() {
  // Load and log database connection
  console.log('Resolving database connection...\n');

  const databaseUrl = loadEnvVariable(ENV_FILE, 'DATABASE_URL');
  const maskedUrl = maskDatabaseUrl(databaseUrl);

  console.log(`Using database: ${maskedUrl}`);
  console.log('✓ Connected successfully\n');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('\nNo SQL migration files found.');
    return;
  }

  // Sort files in alphabetical order
  sqlFiles.sort();

  // Log each filename
  console.log(`\nFound ${sqlFiles.length} migration file(s) to apply:\n`);

  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\nMigration preview complete.');
}

// Execute the preview
previewMigrations();
